package com.digitalbase.ticketing.config;import com.digitalbase.ticketing.security.JwtAuthenticationFilter;import lombok.RequiredArgsConstructor;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.authentication.AuthenticationManager;import org.springframework.security.authentication.AuthenticationProvider;import org.springframework.security.authentication.dao.DaoAuthenticationProvider;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.userdetails.UserDetailsService;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;import org.springframework.web.cors.CorsConfiguration;import org.springframework.web.cors.CorsConfigurationSource;import org.springframework.web.cors.UrlBasedCorsConfigurationSource;import java.util.Arrays;import java.util.List;@Configuration@EnableWebSecurity@EnableMethodSecurity(        securedEnabled = true,        jsr250Enabled = true)@RequiredArgsConstructorpublic class SecurityConfig {    private final UserDetailsService userDetailsService;    private final JwtAuthenticationFilter jwtAuthFilter;    @Bean    public PasswordEncoder passwordEncoder() {        return new BCryptPasswordEncoder();    }    @Bean    public AuthenticationProvider authenticationProvider() {        DaoAuthenticationProvider authProvider =                new DaoAuthenticationProvider(userDetailsService);        authProvider.setPasswordEncoder(passwordEncoder());        return authProvider;    }    @Bean    public AuthenticationManager authenticationManager(            AuthenticationConfiguration authenticationConfiguration    ) throws Exception {        return authenticationConfiguration.getAuthenticationManager();    }    @Bean    public SecurityFilterChain securityFilterChain(            HttpSecurity http    ) throws Exception {        http                .cors(Customizer.withDefaults())                .csrf(csrf -> csrf.disable())                .authorizeHttpRequests(auth -> auth                        .requestMatchers("/uploads/**")                        .permitAll()                        .requestMatchers(                                "/api/auth/login",                                "/api/auth/firebase-login",                                "/api/auth/refresh",                                "/api/auth/signup/init",                                "/api/auth/verify-otp",                                "/api/auth/forgot-password",                                "/api/auth/reset-password"                        )                        .permitAll()                        .requestMatchers("/error")                        .permitAll()                        .anyRequest()                        .authenticated()                )                .sessionManagement(session ->                        session.sessionCreationPolicy(                                SessionCreationPolicy.STATELESS                        )                )                .authenticationProvider(authenticationProvider())                .addFilterBefore(                        jwtAuthFilter,                        UsernamePasswordAuthenticationFilter.class                );        return http.build();    }    @Bean    public CorsConfigurationSource corsConfigurationSource() {        CorsConfiguration configuration =                new CorsConfiguration();        configuration.setAllowedOriginPatterns(                List.of("*")        );        configuration.setAllowedMethods(                Arrays.asList(                        "GET",                        "POST",                        "PUT",                        "PATCH",                        "DELETE",                        "OPTIONS",                        "HEAD"                )        );        configuration.setAllowedHeaders(                Arrays.asList(                        "Authorization",                        "Content-Type",                        "X-Requested-With",                        "Accept",                        "Origin"                )        );        configuration.setExposedHeaders(                List.of("Authorization")        );        configuration.setAllowCredentials(true);        UrlBasedCorsConfigurationSource source =                new UrlBasedCorsConfigurationSource();        source.registerCorsConfiguration(                "/**",                configuration        );        return source;    }}